{
  "findings": [
    {
      "ref": "[D533]",
      "area": "contact",
      "claim": "A parent can block and report annoying or disruptive players on Roblox.",
      "stance": "mitigation",
      "quote": "Roblox also allows your child to block and report annoying or disruptive players that they may encounter when playing online."
    },
    {
      "ref": "[D533]",
      "area": "contact",
      "claim": "Children under 13 are automatically blocked from direct private chat unless a verified parent changes settings.",
      "stance": "mitigation",
      "quote": "Children under 13 are allowed by default to engage in public text chat with others joining the same experience however they’re automatically blocked from chatting directly with specific players of that or other games on Roblox unless a verified parent changes those settings."
    },
    {
      "ref": "[D533]",
      "area": "contact",
      "claim": "Children under 13 have their posts and chats filtered for inappropriate content and to prevent personal information from being posted.",
      "stance": "mitigation",
      "quote": "Roblox also claims that players under 13 have their posts and chats filtered both for inappropriate content and to prevent personal information from being posted."
    },
    {
      "ref": "[D533]",
      "area": "money",
      "claim": "Roblox offers a monthly subscription called Roblox Premium that includes a monthly deposit of Robux and bonus features ranging from $4.99 to $19.99 per month.",
      "stance": "neutral",
      "quote": "Roblox Premium ranges in cost from $4.99 per month to $19.99 per month."
    },
    {
      "ref": "[D533]",
      "area": "money",
      "claim": "The smallest amount of Robux that can be purchased is 400 for $4.99.",
      "stance": "neutral",
      "quote": "The smallest amount you can purchase is 400 Robux for $4.99."
    },
    {
      "ref": "[D533]",
      "area": "data",
      "claim": "Roblox states that no information is saved or stored when users opt-out of facial age estimation.",
      "stance": "mitigation",
      "quote": "Users are free to opt-out of using facial age estimation if they are not comfortable, though Roblox does say that no information is saved or stored."
    },
    {
      "ref": "[D533]",
      "area": "age_gating",
      "claim": "Users under 13 are automatically barred from accessing Moderate content labeled experiences.",
      "stance": "mitigation",
      "quote": "Note that for users under the age of 9 are automatically barred from accessing Moderate content (though they can freely access content labeled as Minimal or Mild)."
    },
    {
      "ref": "[D533]",
      "area": "age_gating",
      "claim": "Experiences labeled Restricted are only available to 17+ users who verified their ages by completing ID verification.",
      "stance": "mitigation",
      "quote": "Restricted May contain strong violence heavy realistic blood moderate crude humor romantic themes unplayable gambling content the presence of alcohol strong language and or moderate fear. These experiences are only available to 17+ users who verified their ages by completing ID verification."
    },
    {
      "ref": "[D533]",
      "area": "content",
      "claim": "Roblox experiences are labeled with Content Maturity Labels indicating the level of maturity suitable for the experience.",
      "stance": "neutral",
      "quote": "Games in Roblox are all labeled to give parents an idea of the kind of content their kids may encounter."
    },
    {
      "ref": "[D533]",
      "area": "content",
      "claim": "Content Labels within Roblox experiences indicate what type of content is within an experience such as realistic depictions of blood or paid item trading.",
      "stance": "neutral",
      "quote": "Content Labels Indicate what type of content is within an experience such as realistic depictions of blood or paid item trading and are assigned by the creator."
    },
    {
      "ref": "[D533]",
      "area": "developer_record",
      "claim": "No developer fines, breaches, lawsuits or regulatory actions are mentioned in the ESRB parent guide for Roblox.",
      "stance": "neutral",
      "quote": "No developer_record information is provided in the ESRB parent guide excerpt."
    }
  ]
}
